// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.daoimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Queryimport androidx.room.Updateimport com.roshan.persona.database.entity.EpisodicMemoryEntityimport kotlinx.coroutines.flow.Flow/** * NOUS — Episodic memory DAO. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Daointerface EpisodicMemoryDao {    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun insert(entity: EpisodicMemoryEntity): Long    @Update    suspend fun update(entity: EpisodicMemoryEntity)    @Query("SELECT * FROM episodic_memories WHERE id = :id AND is_deleted = 0")    suspend fun getById(id: Long): EpisodicMemoryEntity?    @Query("SELECT * FROM episodic_memories WHERE is_deleted = 0 ORDER BY timestamp DESC LIMIT :limit")    suspend fun getRecent(limit: Int = 50): List<EpisodicMemoryEntity>    @Query("SELECT * FROM episodic_memories WHERE is_hot = 1 AND is_deleted = 0 ORDER BY timestamp DESC")    suspend fun getHotCache(): List<EpisodicMemoryEntity>    @Query("SELECT * FROM episodic_memories WHERE embedding_status = 'pending' AND is_deleted = 0 LIMIT :limit")    suspend fun getPendingEmbeddings(limit: Int = 32): List<EpisodicMemoryEntity>    @Query("UPDATE episodic_memories SET embedding_status = :status WHERE id = :id")    suspend fun updateEmbeddingStatus(id: Long, status: String)    @Query("UPDATE episodic_memories SET importance = :importance, last_accessed = :lastAccessed, last_reinforced = :lastReinforced, decay_constant_days = :decayConstant WHERE id = :id")    suspend fun reinforce(id: Long, importance: Float, lastAccessed: Long, lastReinforced: Long, decayConstant: Float)    @Query("UPDATE episodic_memories SET is_deleted = 1 WHERE id = :id")    suspend fun softDelete(id: Long)    @Query("UPDATE episodic_memories SET is_hot = 0 WHERE is_hot = 1 AND timestamp < :cutoff")    suspend fun expireHotCache(cutoff: Long): Int    @Query("DELETE FROM episodic_memories WHERE is_deleted = 1")    suspend fun vacuumTombstoned(): Int    @Query("SELECT COUNT(*) FROM episodic_memories WHERE is_deleted = 0")    suspend fun count(): Int    @Query("SELECT COUNT(*) FROM episodic_memories WHERE is_deleted = 0")    fun countFlow(): Flow<Int>    @Query("UPDATE episodic_memories SET importance = importance * :decayFactor WHERE is_deleted = 0 AND is_flashbulb = 0")    suspend fun applyDecay(decayFactor: Float): Int    @Query("UPDATE episodic_memories SET is_deleted = 1 WHERE importance < :threshold AND timestamp < :cutoff AND is_deleted = 0 AND is_flashbulb = 0")    suspend fun tombstoneLowImportance(threshold: Float, cutoff: Long): Int}